cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

constexpr int MAX_K = 16;

template <typename T>
__global__ void convtranspose3d_kernel(
    const T* __restrict__ X,     // [N, IC, ID, IH, IW]
    const T* __restrict__ W,     // [IC, OC_per_group, K, K, K]
    const T* __restrict__ Bias,  // [OC] or nullptr
    T* __restrict__ Y,           // [N, OC, OD, OH, OW]
    int N, int IC, int ID, int IH, int IW,
    int OC, int OD, int OH, int OW,
    int K, int stride, int padding, int dilation,
    int IC_per_group, int OC_per_group)
{
  constexpr int Threads = 256;
  constexpr int PVec    = 4;

  const int tid = threadIdx.x;

  const int noc = blockIdx.z;
  const int n   = noc / OC;
  const int oc  = noc % OC;
  const int g   = oc / OC_per_group;
  const int oc_local = oc % OC_per_group;
  const int ic_base  = g * IC_per_group;

  const int64_t P_total = (int64_t)OD * OH * OW;
  const int64_t PTile   = (int64_t)Threads * PVec;
  const int64_t p_block = (int64_t)blockIdx.x * PTile;

  // Strides for X (per-sample)
  const int64_t sXn = (int64_t)IC * ID * IH * IW;
  const int64_t sXc = (int64_t)ID * IH * IW;
  const int64_t sXd = (int64_t)IH * IW;
  const int64_t sXh = (int64_t)IW;

  // Strides for Y (per-sample)
  const int64_t sYn = (int64_t)OC * OD * OH * OW;
  const int64_t sYc = (int64_t)OD * OH * OW;
  const int64_t sYd = (int64_t)OH * OW;
  const int64_t sYh = (int64_t)OW;

  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                         make_shape(IC, ID, IH, IW),
                         make_stride(sXc, sXd, sXh, (int64_t)1));

  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                         make_shape(OC, OD, OH, OW),
                         make_stride(sYc, sYd, sYh, (int64_t)1));

  const int64_t KKK = (int64_t)K * K * K;
  auto mW = make_tensor(make_gmem_ptr(W),
                         make_shape(IC, OC_per_group, K, K, K),
                         make_stride((int64_t)OC_per_group * KKK, KKK,
                                      (int64_t)K * K, (int64_t)K, (int64_t)1));

  // Shared memory holding the weight slice for this output channel:
  // shape (IC_per_group, K, K, K), row-major strides.
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(IC_per_group, K, K, K),
                         make_stride((int64_t)K * K * K, (int64_t)K * K, (int64_t)K, (int64_t)1));

  const int64_t totalW = (int64_t)IC_per_group * KKK;
  for (int64_t idx = tid; idx < totalW; idx += Threads) {
    int ic_local = (int)(idx / KKK);
    int rem = (int)(idx % KKK);
    int kd = rem / (K * K);
    int rem2 = rem % (K * K);
    int kh = rem2 / K;
    int kw = rem2 % K;
    int ic = ic_base + ic_local;
    sW(ic_local, kd, kh, kw) = mW(ic, oc_local, kd, kh, kw);
  }
  __syncthreads();

  float bias_val = 0.0f;
  if (Bias != nullptr) {
    bias_val = (float)Bias[oc];
  }

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int64_t p = p_block + tid + (int64_t)i * Threads;
    if (p >= P_total) continue;

    int od = (int)(p / ((int64_t)OH * OW));
    int64_t rem = p % ((int64_t)OH * OW);
    int oh = (int)(rem / OW);
    int ow = (int)(rem % OW);

    bool  valid_d[MAX_K];
    int   id_val[MAX_K];
    bool  valid_h[MAX_K];
    int   ih_val[MAX_K];
    bool  valid_w[MAX_K];
    int   iw_val[MAX_K];

    #pragma unroll
    for (int kd = 0; kd < K; ++kd) {
      int num = od + padding - kd * dilation;
      bool v = (num % stride == 0);
      int id = num / stride;
      v = v && (id >= 0) && (id < ID);
      valid_d[kd] = v;
      id_val[kd] = id;
    }
    #pragma unroll
    for (int kh = 0; kh < K; ++kh) {
      int num = oh + padding - kh * dilation;
      bool v = (num % stride == 0);
      int ih = num / stride;
      v = v && (ih >= 0) && (ih < IH);
      valid_h[kh] = v;
      ih_val[kh] = ih;
    }
    #pragma unroll
    for (int kw = 0; kw < K; ++kw) {
      int num = ow + padding - kw * dilation;
      bool v = (num % stride == 0);
      int iw = num / stride;
      v = v && (iw >= 0) && (iw < IW);
      valid_w[kw] = v;
      iw_val[kw] = iw;
    }

    float acc = bias_val;

    for (int kd = 0; kd < K; ++kd) {
      if (!valid_d[kd]) continue;
      int id = id_val[kd];
      for (int kh = 0; kh < K; ++kh) {
        if (!valid_h[kh]) continue;
        int ih = ih_val[kh];
        for (int kw = 0; kw < K; ++kw) {
          if (!valid_w[kw]) continue;
          int iw = iw_val[kw];
          #pragma unroll 4
          for (int ic_local = 0; ic_local < IC_per_group; ++ic_local) {
            float xval = (float)mX(ic_base + ic_local, id, ih, iw);
            float wval = (float)sW(ic_local, kd, kh, kw);
            acc += xval * wval;
          }
        }
      }
    }

    mY(oc, od, oh, ow) = static_cast<T>(acc);
  }
}

torch::Tensor convtranspose3d_forward(torch::Tensor x,
                                       torch::Tensor weight,
                                       c10::optional<torch::Tensor> bias,
                                       int stride, int padding, int output_padding,
                                       int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, IC, D, H, W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [IC, OC/groups, K, K, K]");

  int64_t N   = x.size(0);
  int64_t IC  = x.size(1);
  int64_t ID  = x.size(2);
  int64_t IH  = x.size(3);
  int64_t IW  = x.size(4);

  int64_t OC_per_group = weight.size(1);
  int64_t K  = weight.size(2);
  TORCH_CHECK(weight.size(0) == IC, "weight.size(0) must equal IC");
  TORCH_CHECK(weight.size(3) == K && weight.size(4) == K, "kernel must be cubic");
  TORCH_CHECK(K <= 16, "kernel size too large for this kernel implementation");

  TORCH_CHECK(groups > 0 && IC % groups == 0, "invalid groups");
  int64_t IC_per_group = IC / groups;
  TORCH_CHECK(IC_per_group == weight.size(0) / groups * 1 || true, ""); // no-op check placeholder
  int64_t OC = OC_per_group * groups;

  int64_t OD = (ID - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
  int64_t OH = (IH - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
  int64_t OW = (IW - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
  TORCH_CHECK(OD > 0 && OH > 0 && OW > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, OD, OH, OW}, x.options());

  constexpr int Threads = 256;
  constexpr int PVec = 4;
  int64_t P_total = OD * OH * OW;
  int64_t PTile = (int64_t)Threads * PVec;

  dim3 block(Threads);
  dim3 grid((unsigned)((P_total + PTile - 1) / PTile),
            1,
            (unsigned)(N * OC));

  size_t smem_bytes = (size_t)IC_per_group * K * K * K * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(convtranspose3d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }

  convtranspose3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)IC, (int)ID, (int)IH, (int)IW,
      (int)OC, (int)OD, (int)OH, (int)OW,
      (int)K, stride, padding, dilation,
      (int)IC_per_group, (int)OC_per_group
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "convtranspose3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
